    [WT_RESET](code?: number): void {
        this.#nativeHandle?.reset(code ?? 0);
        this.destroy();
    }

    [WT_STOP_SENDING](code?: number): void {
        this.#nativeHandle?.stopSending(code ?? 0);
    }
