// ---------------------------------------------------------------------------
// TLS
// ---------------------------------------------------------------------------

/** TLS configuration for server (cert/key) or client (CA, SNI). */
export type TlsOptions = {
    /** PEM-encoded certificate (server) or CA (client). */
