        if (this.#session) {
            this.#session.close({
                code: info?.closeCode,
                reason: info?.reason,
            });
        }
    }

    /** Internal: session for adapters (not part of spec) */
    async _getSession(): Promise<ClientSession> {
        return this.#sessionPromise;
    }
